import{_ as t,o,c as d,a2 as c}from"./chunks/framework.DqTcMi6E.js";const u=JSON.parse('{"title":"SSP (System Structure and Parameterization)","description":"","frontmatter":{},"headers":[],"relativePath":"languages/ssp.md","filePath":"languages/ssp.md"}'),a={name:"languages/ssp.md"};function l(n,e,s,i,r,g){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="ssp-system-structure-and-parameterization" tabindex="-1">SSP (System Structure and Parameterization) <a class="header-anchor" href="#ssp-system-structure-and-parameterization" aria-label="Permalink to &quot;SSP (System Structure and Parameterization)&quot;">​</a></h1><p><code>@modelscript/ssp</code> (<code>languages/ssp</code>) implements the Modelica Association <strong>SSP 1.0 / 2.0</strong> standard for packaging and coupling Functional Mock-up Units (FMUs) into multi-domain Co-Simulation architectures.</p><hr><h2 id="supported-extensions-container-architecture" tabindex="-1">Supported Extensions &amp; Container Architecture <a class="header-anchor" href="#supported-extensions-container-architecture" aria-label="Permalink to &quot;Supported Extensions &amp; Container Architecture&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Extension</th><th style="text-align:left;">Standard Artifact</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><code>.ssp</code></td><td style="text-align:left;">System Structure Package (ZIP archive)</td><td style="text-align:left;">Container bundling <code>SystemStructure.ssd</code>, <code>resources/*.fmu</code>, and <code>*.ssv</code> parameter sets</td></tr><tr><td style="text-align:left;"><code>.ssd</code></td><td style="text-align:left;">System Structure Description (XML)</td><td style="text-align:left;">Hierarchical <code>System</code>, <code>Components</code>, <code>Connectors</code>, <code>Connections</code>, and <code>DefaultExperiment</code> topology</td></tr><tr><td style="text-align:left;"><code>.ssv</code></td><td style="text-align:left;">System Structure Parameter Values (XML)</td><td style="text-align:left;">Typed parameter bindings (<code>Real</code>, <code>Integer</code>, <code>Boolean</code>, <code>String</code>, <code>Enumeration</code>)</td></tr></tbody></table><h3 id="virtual-file-system-vfs-archive-extraction" tabindex="-1">Virtual File System (VFS) Archive Extraction <a class="header-anchor" href="#virtual-file-system-vfs-archive-extraction" aria-label="Permalink to &quot;Virtual File System (VFS) Archive Extraction&quot;">​</a></h3><p>When a <code>.ssp</code> ZIP archive is loaded into the workspace, <code>sspLanguage.container</code> (<code>languages/ssp/src/language.ts</code>) automatically unpacks and indexes its internal artifacts:</p><ul><li><code>*.ssd</code> and <code>*.ssv</code> entries are dispatched via <code>parse_as_language</code> into the <code>@modelscript/ssp</code> CST &amp; Salsa index.</li><li><code>resources/*.fmu</code> archives are recursively extracted (<code>extract_nested</code>) so their internal <code>modelDescription.xml</code> ports and parameters are cross-checked against <code>.ssd</code> connectors.</li><li>Auxiliary tables and binaries under <code>resources/*</code> are mounted into the in-memory VFS (<code>mount_vfs</code>).</li></ul><hr><h2 id="interactive-2d-diagram-builder-bidirectional-xml-writeback" tabindex="-1">Interactive 2D Diagram Builder &amp; Bidirectional XML Writeback <a class="header-anchor" href="#interactive-2d-diagram-builder-bidirectional-xml-writeback" aria-label="Permalink to &quot;Interactive 2D Diagram Builder &amp; Bidirectional XML Writeback&quot;">​</a></h2><p><code>languages/ssp/src/diagram.ts</code> provides a two-way schematic editor for <code>.ssd</code> topologies:</p><ul><li><strong>2D Schematic Extraction (<code>buildSspDiagramData</code>)</strong>: Parses <code>&lt;ssd:System&gt;</code>, <code>&lt;ssd:Component&gt;</code>, <code>&lt;ssd:Connector&gt;</code>, <code>&lt;ssd:Connection&gt;</code>, and <code>&lt;ssd:ElementGeometry&gt;</code> / <code>&lt;ssd:ConnectionGeometry&gt;</code> annotations into positioned block nodes, typed causal ports, and orthogonal routing waypoints.</li><li><strong>Surgical XML Writeback (<code>applySspDiagramEdits</code> / <code>sspLanguage.writeback</code>)</strong>: Moving components, adding/removing FMU blocks, drawing <code>&lt;ssd:Connection&gt;</code> wires, or editing <code>&lt;ssv:Parameter&gt;</code> values updates the underlying <code>.ssd</code> or <code>.ssv</code> XML document in place while preserving namespace prefixes and custom vendor annotations.</li></ul><hr><h2 id="modelica-architecture-projection-ssptomodelicablock" tabindex="-1">Modelica Architecture Projection (<code>sspToModelicaBlock</code>) <a class="header-anchor" href="#modelica-architecture-projection-ssptomodelicablock" aria-label="Permalink to &quot;Modelica Architecture Projection (`sspToModelicaBlock`)&quot;">​</a></h2><p><code>sspToModelicaBlock(ssdDoc)</code> (<code>languages/ssp/src/index.ts</code>) projects any <code>.ssd</code> system topology into an equivalent composite Modelica <code>model</code>, translating <code>&lt;ssd:Connector&gt;</code> definitions into <code>Modelica.Blocks.Interfaces.RealInput</code> / <code>RealOutput</code> (or <code>Integer</code>/<code>Boolean</code> causal interfaces), <code>&lt;ssd:Component&gt;</code> blocks into typed sub-models with <code>&lt;ssv:Parameter&gt;</code> modifications, and <code>&lt;ssd:Connection&gt;</code> edges into <code>connect(...)</code> equations.</p><hr><h2 id="semantic-linter-20-diagnostic-codes" tabindex="-1">Semantic Linter &amp; 20 Diagnostic Codes <a class="header-anchor" href="#semantic-linter-20-diagnostic-codes" aria-label="Permalink to &quot;Semantic Linter &amp; 20 Diagnostic Codes&quot;">​</a></h2><p><code>lintSsd</code> and <code>lintSsv</code> (<code>languages/ssp/src/linter.ts</code>) validate structural, causal, and type soundness across <code>.ssd</code> and <code>.ssv</code> files with 20 diagnostic codes (13 <code>SSP_*</code> + 7 <code>SSV_*</code>):</p><h3 id="ssd-system-structure-diagnostics-lintssd" tabindex="-1"><code>.ssd</code> System Structure Diagnostics (<code>lintSsd</code>) <a class="header-anchor" href="#ssd-system-structure-diagnostics-lintssd" aria-label="Permalink to &quot;`.ssd` System Structure Diagnostics (`lintSsd`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Code</th><th style="text-align:left;">Severity</th><th style="text-align:left;">Condition Checked</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SSP_EMPTY_CONNECTOR_NAME</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">A <code>&lt;Connector&gt;</code> on a system or component has an empty <code>name</code> attribute</td></tr><tr><td style="text-align:left;"><code>SSP_DUPLICATE_CONNECTOR</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">Duplicate connector <code>name</code> declared on the same system or component</td></tr><tr><td style="text-align:left;"><code>SSP_INVALID_CONNECTOR_KIND</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">Connector <code>kind</code> is not one of <code>input</code>, <code>output</code>, <code>parameter</code>, <code>calculatedParameter</code>, <code>local</code>, <code>inout</code></td></tr><tr><td style="text-align:left;"><code>SSP_EMPTY_COMPONENT_NAME</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">A <code>&lt;Component&gt;</code> element has an empty <code>name</code> attribute</td></tr><tr><td style="text-align:left;"><code>SSP_DUPLICATE_COMPONENT</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">Two <code>&lt;Component&gt;</code> elements in the same <code>&lt;System&gt;</code> share the same <code>name</code></td></tr><tr><td style="text-align:left;"><code>SSP_MISSING_COMPONENT_SOURCE</code></td><td style="text-align:left;"><code>warning</code></td><td style="text-align:left;">A <code>&lt;Component&gt;</code> has an empty <code>source</code> URI (no FMU or nested <code>.ssp</code> referenced)</td></tr><tr><td style="text-align:left;"><code>SSP_UNRESOLVED_ELEMENT</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">A <code>&lt;Connection&gt;</code> references a <code>startElement</code> or <code>endElement</code> component that does not exist</td></tr><tr><td style="text-align:left;"><code>SSP_UNRESOLVED_CONNECTOR</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">A <code>&lt;Connection&gt;</code> references a <code>startConnector</code> or <code>endConnector</code> that does not exist on the target element</td></tr><tr><td style="text-align:left;"><code>SSP_SELF_CONNECTION</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">A <code>&lt;Connection&gt;</code> connects an element&#39;s connector back to the exact same element and connector</td></tr><tr><td style="text-align:left;"><code>SSP_CONNECTOR_TYPE_MISMATCH</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">Connected <code>startConnector</code> and <code>endConnector</code> have incompatible data types (e.g., <code>Real</code> connected to <code>Boolean</code>)</td></tr><tr><td style="text-align:left;"><code>SSP_CONNECTOR_CAUSALITY_CONFLICT</code></td><td style="text-align:left;"><code>warning</code></td><td style="text-align:left;">Invalid causal connection (e.g., component <code>output</code> to component <code>output</code>, or <code>input</code> to <code>input</code>)</td></tr><tr><td style="text-align:left;"><code>SSP_UNRESOLVED_BINDING_PREFIX</code></td><td style="text-align:left;"><code>warning</code></td><td style="text-align:left;"><code>&lt;Parameter&gt;</code> <code>name=&quot;prefix.param&quot;</code> in an inline <code>&lt;ParameterValues&gt;</code> block references a non-existent component <code>prefix</code></td></tr><tr><td style="text-align:left;"><code>SSP_INVALID_EXPERIMENT_BOUNDS</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;"><code>&lt;DefaultExperiment&gt;</code> has <code>stopTime &lt;= startTime</code></td></tr></tbody></table><h3 id="ssv-parameter-value-diagnostics-lintssv" tabindex="-1"><code>.ssv</code> Parameter Value Diagnostics (<code>lintSsv</code>) <a class="header-anchor" href="#ssv-parameter-value-diagnostics-lintssv" aria-label="Permalink to &quot;`.ssv` Parameter Value Diagnostics (`lintSsv`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Code</th><th style="text-align:left;">Severity</th><th style="text-align:left;">Condition Checked</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SSV_EMPTY_PARAMETER_NAME</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">A <code>&lt;ssv:Parameter&gt;</code> element has an empty <code>name</code> attribute</td></tr><tr><td style="text-align:left;"><code>SSV_DUPLICATE_PARAMETER</code></td><td style="text-align:left;"><code>warning</code></td><td style="text-align:left;">The same parameter <code>name</code> is defined more than once in the <code>&lt;ssv:Parameters&gt;</code> set</td></tr><tr><td style="text-align:left;"><code>SSV_MISSING_PARAMETER_TYPE</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">A <code>&lt;ssv:Parameter&gt;</code> is missing its child type element (<code>&lt;Real&gt;</code>, <code>&lt;Integer&gt;</code>, <code>&lt;Boolean&gt;</code>, <code>&lt;String&gt;</code>, <code>&lt;Enumeration&gt;</code>)</td></tr><tr><td style="text-align:left;"><code>SSV_MISSING_PARAMETER_VALUE</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;">The typed child element of <code>&lt;ssv:Parameter&gt;</code> is missing its <code>value</code> attribute</td></tr><tr><td style="text-align:left;"><code>SSV_INVALID_REAL_VALUE</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;"><code>&lt;ssv:Real value=&quot;...&quot;/&gt;</code> is not a valid finite floating-point number</td></tr><tr><td style="text-align:left;"><code>SSV_INVALID_INTEGER_VALUE</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;"><code>&lt;ssv:Integer value=&quot;...&quot;/&gt;</code> is not a valid base-10 integer</td></tr><tr><td style="text-align:left;"><code>SSV_INVALID_BOOLEAN_VALUE</code></td><td style="text-align:left;"><code>error</code></td><td style="text-align:left;"><code>&lt;ssv:Boolean value=&quot;...&quot;/&gt;</code> is not <code>&quot;true&quot;</code>, <code>&quot;false&quot;</code>, <code>&quot;1&quot;</code>, or <code>&quot;0&quot;</code></td></tr></tbody></table><hr><h2 id="polyglot-tgg-rules" tabindex="-1">Polyglot TGG Rules <a class="header-anchor" href="#polyglot-tgg-rules" aria-label="Permalink to &quot;Polyglot TGG Rules&quot;">​</a></h2><p><code>@modelscript/ssp</code> registers 8 bidirectional Triple Graph Grammar (TGG) rules in <code>languages/ssp/src/language.ts</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Rule Name</th><th style="text-align:left;">Source (<code>ssp</code>)</th><th style="text-align:left;">Target Language</th><th style="text-align:left;">Target Construct</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SspSystemToModelicaModel</code></td><td style="text-align:left;"><code>SsdSystem</code></td><td style="text-align:left;"><code>modelica</code></td><td style="text-align:left;"><code>ClassDefinition</code> (<code>model</code>)</td></tr><tr><td style="text-align:left;"><code>SspComponentToModelicaComponent</code></td><td style="text-align:left;"><code>SsdComponent</code></td><td style="text-align:left;"><code>modelica</code></td><td style="text-align:left;"><code>ComponentClause</code></td></tr><tr><td style="text-align:left;"><code>SspConnectorToModelicaConnector</code></td><td style="text-align:left;"><code>SsdConnector</code></td><td style="text-align:left;"><code>modelica</code></td><td style="text-align:left;"><code>ComponentClause</code> (<code>RealInput</code> / <code>RealOutput</code>)</td></tr><tr><td style="text-align:left;"><code>SspConnectionToModelicaConnect</code></td><td style="text-align:left;"><code>SsdConnection</code></td><td style="text-align:left;"><code>modelica</code></td><td style="text-align:left;"><code>ConnectClause</code></td></tr><tr><td style="text-align:left;"><code>SspSystemToSysmlPackage</code></td><td style="text-align:left;"><code>SsdSystem</code></td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>PartDef</code></td></tr><tr><td style="text-align:left;"><code>SspComponentToSysmlPart</code></td><td style="text-align:left;"><code>SsdComponent</code></td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>PartUsage</code></td></tr><tr><td style="text-align:left;"><code>SspConnectorToSysmlPort</code></td><td style="text-align:left;"><code>SsdConnector</code></td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>PortUsage</code></td></tr><tr><td style="text-align:left;"><code>SspConnectionToSysmlConnection</code></td><td style="text-align:left;"><code>SsdConnection</code></td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>ConnectionUsage</code></td></tr></tbody></table>',26)])])}const y=t(a,[["render",l]]);export{u as __pageData,y as default};
